package com.opensocket.aievent.core.fingerprint;
import java.util.Set;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.configuration.runtime.RuntimeConfigurationEffectiveValueResolver;
@Component public final class FingerprintRuntimeConfigurationEffectiveValueResolver implements RuntimeConfigurationEffectiveValueResolver{
 private final FingerprintRuntimeConfigurationView view;public FingerprintRuntimeConfigurationEffectiveValueResolver(FingerprintRuntimeConfigurationView view){this.view=view;}@Override public String owner(){return "CORE_FINGERPRINT";}@Override public Set<String> supportedKeys(){return FingerprintRuntimeConfigurationView.ALL;}@Override public Object resolve(String key){return switch(key){case FingerprintRuntimeConfigurationView.ENABLED->view.enabled();case FingerprintRuntimeConfigurationView.POLICY_VERSION->view.policyVersion();case FingerprintRuntimeConfigurationView.DEFAULT_FIELDS->view.defaultFields();case FingerprintRuntimeConfigurationView.MASKING_ENABLED->view.maskingEnabled();case FingerprintRuntimeConfigurationView.MASKING_RULES->view.maskingRulesProjection();case FingerprintRuntimeConfigurationView.POLICIES->view.policiesProjection();default->throw new IllegalArgumentException("CORE_FINGERPRINT_RUNTIME_CONFIG_KEY_NOT_OWNED key="+key);};}}
